/// Stage 5 interim: compile input.ky/.tyb → output via Rust host (not runtime selfhost).
/// With `--selfhost`, emit single-file PE/ELF with embedded startup (+ runtime on Linux).
fn cmd_bootstrap(args: &[String]) -> Result<(), types::IsaError> {
    let mut runtime = false;
    let mut target = platform::PlatformKind::Win32;
    let mut rest: Vec<String> = Vec::new();
    for a in args {
        if a == "--selfhost" {
            runtime = true;
        } else if let Some(t) = a.strip_prefix("--target=") {
            target = platform::parse_platform(t)?;
        } else {
            rest.push(a.clone());
        }
    }
    if rest.len() != 2 {
        usage();
    }
    if rest[1].ends_with(".elf") {
        target = platform::PlatformKind::Linux;
    }
    let is_linux = matches!(target, platform::PlatformKind::Linux);

    if runtime {
        let input = fs::read(&rest[0]).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        if is_linux {
            let elf = if tyb_parser::is_tyb(&input) {
                selfhost::bootstrap_selfhost_runtime_linux(&input)?
            } else {
                let src = std::str::from_utf8(&input).map_err(|e| types::IsaError::ParseError {
                    line: 0,
                    msg: format!("bootstrap --selfhost input not UTF-8 .ty: {e}"),
                })?;
                let out = executor::compile_ty_source(src, platform::PlatformKind::Linux)?;
                let hot = selfhost::build_hot(&out.handler_offsets);
                selfhost::link_elf_selfhost_runtime(&out.code, &out.data, &hot)?
            };
            fs::write(&rest[1], &elf).map_err(|e| types::IsaError::IoError {
                msg: e.to_string(),
            })?;
            let so_path = std::path::Path::new(&rest[1])
                .parent()
                .unwrap_or(std::path::Path::new("."))
                .join(linux_selfhost::RUNTIME_SO_NAME);
            let so = selfhost::runtime_so_bytes()?;
            fs::write(&so_path, &so).map_err(|e| types::IsaError::IoError {
                msg: format!("write {}: {e}", so_path.display()),
            })?;
            println!(
                "bootstrap --selfhost: {} → {} ({} bytes, embedded startup + {})",
                rest[0],
                rest[1],
                elf.len(),
                linux_selfhost::RUNTIME_SO_NAME
            );
            seed_host::emit_observe("bootstrap-selfhost", "linux", &elf, Some(so.len()));
            return Ok(());
        }

        let pe = if tyb_parser::is_tyb(&input) {
            selfhost::bootstrap_selfhost_runtime(&input)?
        } else {
            let src = std::str::from_utf8(&input).map_err(|e| types::IsaError::ParseError {
                line: 0,
                msg: format!("bootstrap --selfhost input not UTF-8 .ty: {e}"),
            })?;
            let out = executor::compile_ty_source(src, PlatformKind::Win32)?;
            let hot = selfhost::build_hot(&out.handler_offsets);
            let dll = selfhost::runtime_dll_bytes()?;
            selfhost::link_pe_selfhost_runtime(&out.code, &out.data, &hot, &dll)?
        };
        fs::write(&rest[1], &pe).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        let dll_len = selfhost::runtime_dll_bytes()?.len();
        println!(
            "bootstrap --selfhost: {} → {} ({} bytes, embedded startup + runtime {} bytes in PE)",
            rest[0],
            rest[1],
            pe.len(),
            dll_len
        );
        seed_host::emit_observe("bootstrap-selfhost", "win32", &pe, Some(dll_len));
        return Ok(());
    }
    if rest.len() != 2 {
        usage();
    }
    let input = fs::read(&rest[0]).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    // Stage 13-A: bootstrap without --selfhost IS the seed/link host (≡ `yoyo link`).
    let out_bytes = if is_linux {
        selfhost::seed_host_compile_linux(&input)?
    } else {
        selfhost::seed_host_compile(&input)?
    };
    fs::write(&rest[1], &out_bytes).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    println!(
        "seed/link host (Stage 13-A): {} → {} ({} bytes; not --selfhost)",
        rest[0],
        rest[1],
        out_bytes.len()
    );
    let target_label = if is_linux { "linux" } else { "win32" };
    // Post-v1.0 H_00 (Win+Linux): no exact-embed of Rust runtime (cwd sidecar).
    let embed = None;
    seed_host::emit_observe("bootstrap", target_label, &out_bytes, embed);
    Ok(())
}

fn cmd_diff(args: &[String]) -> Result<(), types::IsaError> {
    let mut selfhost_body = false;
    let mut paths: Vec<&str> = Vec::new();
    for a in args {
        if a == "--selfhost-body" {
            selfhost_body = true;
        } else if a.starts_with('-') {
            usage();
        } else {
            paths.push(a.as_str());
        }
    }
    if paths.len() != 2 {
        usage();
    }
    let a = fs::read(paths[0]).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let b = fs::read(paths[1]).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let report = if selfhost_body {
        let ta = ddc::pe_text_section(&a)?;
        let tb = ddc::pe_text_section(&b)?;
        let emit = ddc::infer_shared_emit_code_len(&ta, &tb);
        println!(
            "selfhost-body: emit_code_bytes={emit} (min trimmed; skips H_00 slot)"
        );
        let stub_a = ddc::h00_stub_tail(&ta, emit);
        let stub_b = ddc::h00_stub_tail(&tb, emit);
        let stub_a_nz = stub_a
            .iter()
            .rposition(|&b| b != 0)
            .map(|i| i + 1)
            .unwrap_or(0);
        let stub_b_nz = stub_b
            .iter()
            .rposition(|&b| b != 0)
            .map(|i| i + 1)
            .unwrap_or(0);
        println!(
            "selfhost-body: stub_tail_nonzero a={stub_a_nz} b={stub_b_nz} (honest DIFF if Rust-only)"
        );
        ddc::compare_pe_selfhost_body(&a, &b, emit)?
    } else {
        ddc::compare_pe_text(&a, &b)?
    };
    println!("compared_bytes: {}", report.compared_bytes);
    println!("hash_a: {}", report.hash_a);
    println!("hash_b: {}", report.hash_b);
    if report.equal {
        println!("DDC: EQUAL");
        Ok(())
    } else {
        println!("DDC: DIFFER");
        Err(types::IsaError::ParseError {
            line: 0,
            msg: "DDC mismatch".into(),
        })
    }
}

