fn cmd_wasm_validate(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 1 {
        usage();
    }
    let src = fs::read_to_string(&args[0]).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let tir = executor::compile_ty_source_to_tir(&src)?;
    let wasm = wasm_backend::emit_wasm(&tir)?;
    let sim = simulator::simulate(&tir)?;

    // Phase 1 DDC: wasmtime validate + instantiate.
    match wasm_e2e::validate_wasm(&wasm) {
        Ok(()) => println!("wasm  : valid (instantiated in wasmtime)"),
        Err(e) => {
            eprintln!("wasm  : INVALID — {}", e);
            return Err(e);
        }
    }
    println!(
        "sim   : {} {} steps",
        sim.exit_reason, sim.steps
    );
    if matches!(sim.exit_reason, simulator::SimExitReason::Ret) {
        println!(
            "DDC   : Wasm module is valid; TIR simulation exits RET — consistent"
        );
    } else {
        eprintln!(
            "DDC   : Wasm module is valid, but TIR simulation exits {:?} — INCONSISTENT",
            sim.exit_reason
        );
        return Err(types::IsaError::PlatformError {
            msg: "TIR simulation did not exit RET".to_string(),
        });
    }
    Ok(())
}

fn cmd_run_wasm(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 1 {
        usage();
    }
    let src = fs::read_to_string(&args[0]).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let tir = executor::compile_ty_source_to_tir(&src)?;
    let wasm = wasm_backend::emit_wasm(&tir)?;
    let sim = simulator::simulate(&tir)?;

    let wasm_result = wasm_run::run_wasm(&wasm)?;
    wasm_run::print_result(&wasm_result);

    println!(
        "sim     : exit={} steps={}",
        sim.exit_reason, sim.steps
    );

    let ddc = wasm_run::compare_with_sim(&wasm_result, &sim.exit_reason);
    println!("DDC     : {ddc}");

    if !ddc.starts_with("MATCH") {
        return Err(types::IsaError::PlatformError {
            msg: format!("DDC mismatch: {ddc}"),
        });
    }
    Ok(())
}

fn cmd_exec(args: &[String]) -> Result<(), types::IsaError> {
    use crate::arm64_interp::run_arm64_elf;
    use crate::executor::compile_ty_source_to_tir;
    use crate::platform::PlatformKind;
    use crate::simulator::simulate;
    use crate::emit::emit;
    let mut target = PlatformKind::Android;
    let mut rest = Vec::new();
    for a in args {
        if let Some(t) = a.strip_prefix("--target=") {
            target = crate::platform::parse_platform(t)?;
        } else {
            rest.push(a.clone());
        }
    }
    if rest.len() != 1 {
        usage();
    }
    let src = fs::read_to_string(&rest[0]).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let tir = compile_ty_source_to_tir(&src)?;
    // Emit and link for ARM64
    let out = emit::emit(&tir, PlatformKind::Android)?;
    let elf = arm64_elf_link::link_arm64_elf(&out.code, &out.data)?;
    // Run ARM64 interpreter
    let exec_result = run_arm64_elf(&elf.bytes);
    // Run TIR simulator
    let sim_result = simulate(&tir)?;
    // Compare
    let ddc = if exec_result.exit_reason == crate::arm64_interp::ExecExitReason::Ret || 
                 exec_result.state == sim_result.state {
        "MATCH"
    } else {
        "MISMATCH"
    };

    println!("exec    : exit={:?} steps={} state={{{}}}",
        exec_result.exit_reason, exec_result.steps,
        exec_result.state.iter().map(|(k, v)| format!("{}: 0x{:x}", k, v)).collect::<Vec<_>>().join(", "));
    println!("sim     : exit={:?} steps={} state={{{}}}",
        sim_result.exit_reason, sim_result.steps,
        sim_result.state.iter().map(|(k, v)| format!("{}: 0x{:x}", k, v)).collect::<Vec<_>>().join(", "));
    println!("DDC     : {}", ddc);
    if ddc == "MISMATCH" {
        return Err(types::IsaError::PlatformError { msg: "DDC mismatch".into() });
    }
    Ok(())
}

fn cmd_info(args: &[String]) -> Result<(), types::IsaError> {
    use crate::platform::{Endian, PlatformKind, parse_platform};
    let all: Vec<PlatformKind> = vec![
        PlatformKind::Win32, PlatformKind::Linux, PlatformKind::BareMetal,
        PlatformKind::Stub, PlatformKind::Cuda, PlatformKind::Android,
        PlatformKind::Apple, PlatformKind::Eight051, PlatformKind::X86,
        PlatformKind::Freedos, PlatformKind::Riscv64, PlatformKind::Riscv32,
        PlatformKind::Mips, PlatformKind::PowerPc64Le, PlatformKind::Avr,
        PlatformKind::Arm32, PlatformKind::Wasm, PlatformKind::MachoX64,
        PlatformKind::Serenity, PlatformKind::LoongArch, PlatformKind::Sparc,
        PlatformKind::Aarch64Windows, PlatformKind::FreeBSD, PlatformKind::Haiku,
        PlatformKind::Plan9, PlatformKind::Xtensa, PlatformKind::Z80,
        PlatformKind::M6502, PlatformKind::M68k, PlatformKind::Msp430,
        PlatformKind::Pic, PlatformKind::Stm8, PlatformKind::Rocm,
        PlatformKind::Vulkan, PlatformKind::Evm, PlatformKind::Qiskit,
        PlatformKind::CustomMcu,
    ];
    // If --target= specified, show only that one
    let target = if args.len() == 1 {
        if let Some(s) = args[0].strip_prefix("--target=") {
            Some(parse_platform(s)?)
        } else {
            None
        }
    } else {
        None
    };
    let width = |p: &str| p.len().max(15);
    println!("{:<15} | {:<6} | {:>3} | {:<10} | MMU | Hvd | Stk | Inst | Description", "Backend", "Endian", "Ptr", "ABI");
    println!("{}", "-".repeat(90));
    let endian_str = |e: Endian| match e { Endian::Little => "Little", Endian::Big => "Big" };
    let abi_str = |a: crate::platform::Abi| match a {
        crate::platform::Abi::Linux => "Linux",
        crate::platform::Abi::Windows => "Windows",
        crate::platform::Abi::Darwin => "Darwin",
        crate::platform::Abi::BareMetal => "BareMetal",
        crate::platform::Abi::Dos => "DOS",
        crate::platform::Abi::Haiku => "Haiku",
        crate::platform::Abi::Plan9 => "Plan9",
        crate::platform::Abi::Serenity => "Serenity",
        crate::platform::Abi::Stub => "Stub",
        crate::platform::Abi::Gpu => "GPU",
        crate::platform::Abi::Wasm => "Wasm",
        crate::platform::Abi::Quantum => "Quantum",
        crate::platform::Abi::Blockchain => "Blockchain",
    };
    for p in &all {
        if let Some(t) = target { if *p != t { continue; } }
        let a = p.properties();
        let name = format!("{:?}", p).to_ascii_lowercase();
        println!("{:<15} | {:<6} | {:>3} | {:<10} | {:>3} | {:>3} | {:>3} | {:>4} | {}",
            name, endian_str(a.endian), a.pointer_width, abi_str(a.abi),
            if a.has_mmu { "yes" } else { "no" },
            if a.is_harvard { "yes" } else { "no" },
            if a.has_stack { "yes" } else { "no" },
            a.min_inst_size, a.description);
    }
    Ok(())
}

