/// Stage 5 GEN12: gen1≡gen2 — `.ty` link vs `.tyb` bootstrap/link, .text DDC EQUAL.
fn cmd_test_gen12() -> Result<(), types::IsaError> {
    let root = repo_root()?;
    let ty = root.join("yoyo/projects/yoyo.ty");
    let tyb = root.join("yoyo/projects/yoyo.tyb");
    if !ty.is_file() {
        return Err(types::IsaError::IoError {
            msg: format!("missing {}", ty.display()),
        });
    }
    if !tyb.is_file() {
        return Err(types::IsaError::IoError {
            msg: format!(
                "missing {} — run: python scripts/ty2tyb.py",
                tyb.display()
            ),
        });
    }

    let src = fs::read_to_string(&ty).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let tyb_data = fs::read(&tyb).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;

    let out_ty = executor::compile_ty_source(&src, PlatformKind::Win32)?;
    let gen1 = pe_link::link_pe_win32(&out_ty.code, &out_ty.data, &out_ty.handler_offsets)?.bytes;

    let gen2 = selfhost::bootstrap_compile(&tyb_data)?;

    let out_tyb = executor::compile_tyb_source(&tyb_data, PlatformKind::Win32)?;
    let gen2_link = pe_link::link_pe_win32(&out_tyb.code, &out_tyb.data, &out_tyb.handler_offsets)?.bytes;

    let pairs: [(&str, &[u8], &str, &[u8]); 2] = [
        ("gen1(.ty link)", &gen1, "gen2(.tyb bootstrap)", &gen2),
        ("gen1(.ty link)", &gen1, "gen2b(.tyb link)", &gen2_link),
    ];

    let mut all_ok = true;
    let mut sha: Option<String> = None;

    for (name_a, a, name_b, b) in pairs {
        let report = ddc::compare_pe_text(a, b)?;
        println!(
            "GEN12: {name_a} vs {name_b}: compared_bytes={}",
            report.compared_bytes
        );
        println!("  hash_a: {}", report.hash_a);
        println!("  hash_b: {}", report.hash_b);
        if report.equal {
            println!("  DDC: EQUAL");
            if sha.is_none() {
                sha = Some(report.hash_a.clone());
            } else if sha.as_ref() != Some(&report.hash_a) {
                all_ok = false;
            }
        } else {
            println!("  DDC: DIFFER");
            all_ok = false;
        }
    }

    if let Some(ref h) = sha {
        println!("SHA-256 (.text): {h}");
        println!("SHA prefix: {}", &h[..8.min(h.len())]);
    }

    if all_ok {
        println!("gen1≡gen2 (.ty==.tyb DDC): PASS");
        Ok(())
    } else {
        Err(types::IsaError::PlatformError {
            msg: "gen12 DDC mismatch".into(),
        })
    }
}

/// Stage 8-B FULLBODY: full `yoyo.ty` body (not W-SM scoped subset) compiles self-host
/// input and produces a runnable gen binary; `.text` bytes are in gen12 DDC scope.
fn cmd_test_fullbody() -> Result<(), types::IsaError> {
    use std::process::Command;

    const MIN_FULL_BODY_HANDLERS: usize = 700;
    const W_SM_SCOPED_HANDLERS: usize = 34;

    let root = repo_root()?;
    let ty = root.join("yoyo/projects/yoyo.ty");
    let tyb = root.join("yoyo/projects/yoyo.tyb");
    if !ty.is_file() || !tyb.is_file() {
        return Err(types::IsaError::IoError {
            msg: "missing yoyo/projects/yoyo.ty or yoyo.tyb".into(),
        });
    }

    let src = fs::read_to_string(&ty).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let tyb_data = fs::read(&tyb).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;

    let out = executor::compile_ty_source(&src, PlatformKind::Win32)?;
    let n_handlers = out.handler_offsets.len();
    println!("FULLBODY: handlers={n_handlers} (min {MIN_FULL_BODY_HANDLERS}, W-SM scoped={W_SM_SCOPED_HANDLERS})");
    if n_handlers < MIN_FULL_BODY_HANDLERS {
        return Err(types::IsaError::PlatformError {
            msg: format!(
                "full body handler count {n_handlers} < {MIN_FULL_BODY_HANDLERS} — looks like scoped subset only"
            ),
        });
    }

    let gen1 = pe_link::link_pe_win32(&out.code, &out.data, &out.handler_offsets)?.bytes;
    let gen2 = selfhost::bootstrap_compile(&tyb_data)?;

    let report = ddc::compare_pe_text(&gen1, &gen2)?;
    println!(
        "FULLBODY: gen1(.ty) vs gen2(.tyb bootstrap): compared_bytes={}",
        report.compared_bytes
    );
    println!("  hash: {}", report.hash_a);
    if !report.equal {
        return Err(types::IsaError::PlatformError {
            msg: "fullbody gen1≡gen2 DDC mismatch".into(),
        });
    }
    println!("  DDC: EQUAL");

    let gen2_ty = selfhost::bootstrap_compile(src.as_bytes())?;
    let report_ty = ddc::compare_pe_text(&gen1, &gen2_ty)?;
    if !report_ty.equal {
        return Err(types::IsaError::PlatformError {
            msg: "fullbody .ty text bootstrap DDC mismatch".into(),
        });
    }
    println!("FULLBODY: .ty text bootstrap DDC EQUAL");

    #[cfg(windows)]
    {
        let gen2rt = selfhost::bootstrap_selfhost_runtime(&tyb_data)?;
        let work = std::env::temp_dir().join(format!("yoyo-fullbody-{}", std::process::id()));
        fs::create_dir_all(&work).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        let gen2rt_path = work.join("gen2rt.exe");
        fs::write(&gen2rt_path, &gen2rt).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        fs::copy(&tyb, work.join("input.tyb")).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;

        let output = work.join("output.exe");
        if output.is_file() {
            let _ = fs::remove_file(&output);
        }

        let status = Command::new(&gen2rt_path)
            .current_dir(&work)
            .status()
            .map_err(|e| types::IsaError::IoError {
                msg: format!("run gen2rt: {e}"),
            })?;
        if !status.success() {
            return Err(types::IsaError::PlatformError {
                msg: format!("fullbody gen2rt exit {}", status),
            });
        }
        if !output.is_file() {
            return Err(types::IsaError::PlatformError {
                msg: "fullbody gen2rt produced no output.exe".into(),
            });
        }

        let gen3 = fs::read(&output).map_err(|e| types::IsaError::IoError {
            msg: e.to_string(),
        })?;
        let report3 = ddc::compare_pe_text(&gen2, &gen3)?;
        if !report3.equal {
            return Err(types::IsaError::PlatformError {
                msg: "fullbody gen3 runtime DDC mismatch".into(),
            });
        }
        println!(
            "FULLBODY: gen2rt runtime → output.exe DDC EQUAL ({} bytes)",
            gen3.len()
        );
    }

    #[cfg(not(windows))]
    {
        println!("FULLBODY: runtime gen2rt smoke SKIP (non-Windows host)");
    }

    println!(
        "FULLBODY: PASS — full body {n_handlers} handlers in gen12 DDC window ({} bytes)",
        report.compared_bytes
    );
    Ok(())
}

/// Stage 12-B: selfhost-body section-ddc on full `yoyo.ty` (Rust gen1≡gen2).
/// Enlarges observability past whole-`.text` three-peer DIFF: compares PE startup +
/// post-H_00 shared handlers; fail-closed requires Rust H_00 LoadLibrary stub present.
fn cmd_test_body_ddc() -> Result<(), types::IsaError> {
    // Post-v1.0 sidecar LoadLibrary stub is shorter than extract+WriteFile (was 100/159).
    const MIN_H00_STUB_NONZERO: usize = 40;

    let root = repo_root()?;
    let ty = root.join("yoyo/projects/yoyo.ty");
    let tyb = root.join("yoyo/projects/yoyo.tyb");
    if !ty.is_file() || !tyb.is_file() {
        return Err(types::IsaError::IoError {
            msg: "missing yoyo/projects/yoyo.ty or yoyo.tyb".into(),
        });
    }

    let src = fs::read_to_string(&ty).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let tyb_data = fs::read(&tyb).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;

    let out = executor::compile_ty_source(&src, PlatformKind::Win32)?;
    let emit_code = out.code.len();
    println!(
        "BODY-DDC: emit_code_bytes={emit_code} handlers={}",
        out.handler_offsets.len()
    );
    if emit_code < ddc::MIN_SHARED_HANDLER_BYTES + ddc::H00_SLOT_LEN {
        return Err(types::IsaError::PlatformError {
            msg: format!("BODY-DDC: emit too small ({emit_code}) — not full selfhost body"),
        });
    }

    let gen1 = pe_link::link_pe_win32(&out.code, &out.data, &out.handler_offsets)?.bytes;
    let gen2 = selfhost::bootstrap_compile(&tyb_data)?;

    let text1 = ddc::pe_text_section(&gen1)?;
    let text2 = ddc::pe_text_section(&gen2)?;
    // Shared emit excludes Rust-only H_00 stub (present on both gen1/gen2 equally —
    // use compile emit_code, not trimmed text, so stub stays outside this window).
    let report = ddc::compare_pe_selfhost_body(&gen1, &gen2, emit_code)?;
    println!(
        "BODY-DDC: gen1 vs gen2 selfhost-body compared_bytes={}",
        report.compared_bytes
    );
    println!("  hash: {}", report.hash_a);
    if !report.equal {
        return Err(types::IsaError::PlatformError {
            msg: "BODY-DDC: gen1≡gen2 selfhost-body mismatch".into(),
        });
    }
    println!("  DDC: EQUAL");

    let stub = ddc::h00_stub_tail(&text1, emit_code);
    let stub_nz = stub
        .iter()
        .rposition(|&b| b != 0)
        .map(|i| i + 1)
        .unwrap_or(0);
    println!(
        "BODY-DDC: H_00 stub tail after emit: raw={} nonzero_span={stub_nz}",
        stub.len()
    );
    if stub_nz < MIN_H00_STUB_NONZERO {
        return Err(types::IsaError::PlatformError {
            msg: format!(
                "BODY-DDC: Rust H_00 extract stub missing/too small ({stub_nz} < {MIN_H00_STUB_NONZERO})"
            ),
        });
    }
    // Full .text still covers stub (gen12 window); pin sizes for trust-chain docs.
    println!(
        "BODY-DDC: full .text lens gen1={} gen2={} (includes H_00 stub; peers may DIFF here)",
        text1.len(),
        text2.len()
    );
    println!(
        "BODY-DDC: PASS — selfhost body window {}B EQUAL; H_00 stub {stub_nz}B pinned (honest: stub/.data DLL still outside three-peer EQUAL)",
        report.compared_bytes
    );
    Ok(())
}

/// Fail-closed pin monitor: `yoyo/projects/yoyo.ty` sha256 must match `yoyo/tests/yoyo.ty.lock`.
/// Does not auto-relock — drift is a hard failure (PROMPT #18 / Decision #13).
fn cmd_test_lock() -> Result<(), types::IsaError> {
    let root = repo_root()?;
    let ty_path = root.join("yoyo/projects/yoyo.ty");
    let lock_path = root.join("yoyo/tests/yoyo.ty.lock");

    let ty_bytes = fs::read(&ty_path).map_err(|e| types::IsaError::IoError {
        msg: format!("read {}: {e}", ty_path.display()),
    })?;
    let lock_text = fs::read_to_string(&lock_path).map_err(|e| types::IsaError::IoError {
        msg: format!("read {}: {e}", lock_path.display()),
    })?;

    let expected = parse_lock_sha256(&lock_text).map_err(|msg| types::IsaError::PlatformError {
        msg,
    })?;
    let actual = ddc::sha256_hex(&ty_bytes);

    if actual != expected {
        eprintln!("LOCK PIN DRIFT: yoyo.ty sha256 mismatch (fail-closed, not auto-relock)");
        eprintln!("  expected (yoyo.ty.lock): {expected}");
        eprintln!("  actual  (yoyo.ty):       {actual}");
        return Err(types::IsaError::PlatformError {
            msg: "yoyo.ty lock pin drift".into(),
        });
    }

    println!("LOCK PIN: PASS sha256={}…", &actual[..16.min(actual.len())]);
    if let Some(signer) = parse_lock_field(&lock_text, "signer") {
        println!("  signed: {signer}");
    }
    if let Some(date) = parse_lock_field(&lock_text, "date") {
        println!("  date: {date}");
    }
    Ok(())
}

fn parse_lock_sha256(lock_text: &str) -> Result<String, String> {
    parse_lock_field(lock_text, "sha256")
        .filter(|s| s.len() == 64 && s.chars().all(|c| c.is_ascii_hexdigit()))
        .ok_or_else(|| "yoyo.ty.lock: missing or invalid sha256 field".into())
}

fn parse_lock_field(lock_text: &str, field: &str) -> Option<String> {
    let needle = format!("\"{field}\": \"");
    let start = lock_text.find(&needle)?;
    let rest = &lock_text[start + needle.len()..];
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}

fn cmd_test(args: &[String]) -> Result<(), types::IsaError> {
    if args.len() != 1 {
        usage();
    }
    match args[0].as_str() {
        "golden" => cmd_test_golden(),
        "backends" => cmd_test_backends(),
        "ddc" => cmd_test_ddc_suite(),
        "gen12" => cmd_test_gen12(),
        "fullbody" => cmd_test_fullbody(),
        "lock" => cmd_test_lock(),
        "body-ddc" => cmd_test_body_ddc(),
        "all" => {
            cmd_test_lock()?;
            cmd_test_golden()?;
            cmd_test_backends()?;
            cmd_test_ddc_suite()?;
            cmd_test_gen12()?;
            cmd_test_fullbody()
        }
        _ => usage(),
    }
}

/// Compile + link a fixture for every platform backend and verify output is non-empty.
fn cmd_test_backends() -> Result<(), types::IsaError> {
    use crate::platform::PlatformKind;
    let fixture = find_fixture("00_nop_ret.ty")?;
    let src = fs::read_to_string(&fixture).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let tir = executor::compile_ty_source_to_tir(&src)?;
    let mut failed = 0u32;
    let mut total = 0u32;
    let targets = [
        PlatformKind::Win32, PlatformKind::Linux, PlatformKind::BareMetal,
        PlatformKind::Stub, PlatformKind::Cuda, PlatformKind::Android,
        PlatformKind::Apple, PlatformKind::Eight051, PlatformKind::X86,
        PlatformKind::Freedos, PlatformKind::Riscv64, PlatformKind::Riscv32,
        PlatformKind::Mips, PlatformKind::PowerPc64Le, PlatformKind::Avr,
        PlatformKind::Arm32, PlatformKind::Wasm, PlatformKind::MachoX64,
        PlatformKind::Serenity, PlatformKind::LoongArch, PlatformKind::Sparc,
        PlatformKind::Aarch64Windows, PlatformKind::FreeBSD, PlatformKind::Haiku,
        PlatformKind::Plan9, PlatformKind::Xtensa, PlatformKind::Z80,
        PlatformKind::M6502, PlatformKind::M68k, PlatformKind::Msp430,
        PlatformKind::Pic, PlatformKind::Stm8, PlatformKind::Rocm,
        PlatformKind::Vulkan, PlatformKind::Evm, PlatformKind::Qiskit,
        PlatformKind::CustomMcu,
    ];
    for target in targets {
        total += 1;
        let name = format!("{:?}", target).to_ascii_lowercase();
        match emit_target_bytes(target, &tir) {
            Ok(bytes) if !bytes.is_empty() => {
                println!("BACKEND {name}: PASS ({} bytes)", bytes.len());
            }
            Ok(_) => {
                failed += 1;
                eprintln!("BACKEND {name}: FAIL (empty output)");
            }
            Err(e) => {
                failed += 1;
                eprintln!("BACKEND {name}: FAIL —{e}");
            }
        }
    }
    println!("backend tests: {}/{} PASS", total - failed, total);
    if failed > 0 { Err(types::IsaError::PlatformError { msg: format!("{failed} backend tests failed") }) } else { Ok(()) }
}

/// Compile + link a target, returning the output bytes.
fn emit_target_bytes(target: crate::platform::PlatformKind, tir: &[crate::tir::TirInst]) -> Result<Vec<u8>, types::IsaError> {
    use crate::platform::PlatformKind;
    let out = emit::emit(tir, target)?;
    match target {
        PlatformKind::Android => Ok(arm64_elf_link::link_arm64_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Apple => Ok(apple_backend::link_macho64(&out.code, &out.data)?.bytes),
        PlatformKind::Linux | PlatformKind::FreeBSD | PlatformKind::Haiku => Ok(elf_link::link_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Riscv64 => Ok(riscv_elf_link::link_riscv_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Riscv32 => Ok(riscv32_elf_link::link_riscv32_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Mips => Ok(mips_elf_link::link_mips_elf(&out.code, &out.data)?.bytes),
        PlatformKind::PowerPc64Le => Ok(ppc_elf_link::link_ppc_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Arm32 => Ok(arm32_elf_link::link_arm32_elf(&out.code, &out.data)?.bytes),
        PlatformKind::X86 => Ok(x86_link::link_x86(&out.code, &out.data)?.bytes),
        PlatformKind::MachoX64 => Ok(macho_x64_link::link_macho_x64(&out.code, &out.data)?.bytes),
        PlatformKind::Aarch64Windows => Ok(arm64_pe_link::link_arm64_pe(&out.code, &out.data)?.bytes),
        PlatformKind::LoongArch => Ok(loongarch_elf_link::link_loongarch_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Sparc => Ok(sparc_elf_link::link_sparc_elf(&out.code, &out.data)?.bytes),
        PlatformKind::Win32 => Ok(pe_link::link_pe(&out.code, &out.data)?.bytes),
        PlatformKind::Wasm => Ok(wasm_backend::emit_wasm(tir)?),
        PlatformKind::Cuda => Ok(cuda_backend::emit_cuda(tir)?.into_bytes()),
        PlatformKind::Rocm => Ok(rocm_backend::emit_rocm(tir)?.into_bytes()),
        PlatformKind::Vulkan => Ok(spirv_backend::emit_spirv(tir)?),
        PlatformKind::Qiskit => Ok(qiskit_backend::emit_qiskit(tir)?.into_bytes()),
        // Flat binary / no linker
        PlatformKind::BareMetal | PlatformKind::Stub | PlatformKind::Eight051
        | PlatformKind::Freedos | PlatformKind::Avr | PlatformKind::Serenity
        | PlatformKind::Plan9 | PlatformKind::Xtensa | PlatformKind::Z80
        | PlatformKind::M6502 | PlatformKind::M68k | PlatformKind::Msp430
        | PlatformKind::Pic | PlatformKind::Stm8 | PlatformKind::Evm
        | PlatformKind::CustomMcu => Ok(out.code),
    }
}

/// Cross-arch DDC consistency: each arch runs in its own `#[inline(never)]`
/// helper so Windows debug stack frames stay small as path count grows.
fn cmd_test_ddc() -> Result<(), types::IsaError> {
    let fixture = find_fixture("00_nop_ret.ty")?;
    let src = fs::read_to_string(&fixture).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let tir = executor::compile_ty_source_to_tir(&src)?;

    let sim_ok = ddc_sim(&tir)?;
    let exec_ok = ddc_arm64(&tir)?;
    let wasm_ok = ddc_wasm(&tir)?;
    let riscv_ok = ddc_riscv64(&tir)?;
    let riscv32_ok = ddc_riscv32(&tir)?;
    let mips_ok = ddc_mips(&tir)?;
    let ppc_ok = ddc_ppc(&tir)?;
    let arm32_ok = ddc_arm32(&tir)?;
    let sparc_ok = ddc_sparc(&tir)?;
    let loong_ok = ddc_loong(&tir)?;
    let e8051_ok = ddc_8051(&tir)?;
    let avr_ok = ddc_avr(&tir)?;
    let x86_ok = ddc_x86(&tir)?;
    let z80_ok = ddc_z80(&tir)?;
    let m6502_ok = ddc_6502(&tir)?;
    let m68k_ok = ddc_m68k(&tir)?;
    let msp430_ok = ddc_msp430(&tir)?;
    let freedos_ok = ddc_freedos(&tir)?;
    let xtensa_ok = ddc_xtensa(&tir)?;
    let pic_ok = ddc_pic(&tir)?;
    let stm8_ok = ddc_stm8(&tir)?;
    let evm_ok = ddc_evm(&tir)?;
    let plan9_ok = ddc_plan9(&tir)?;
    let custom_mcu_ok = ddc_custom_mcu(&tir)?;

    if sim_ok && exec_ok && wasm_ok && riscv_ok && riscv32_ok && mips_ok && ppc_ok && arm32_ok && sparc_ok && loong_ok && e8051_ok && avr_ok && x86_ok && z80_ok && m6502_ok && m68k_ok && msp430_ok && freedos_ok && xtensa_ok && pic_ok && stm8_ok && evm_ok && plan9_ok && custom_mcu_ok {
        println!("DDC test: PASS (sim=Ret exec=Ret wasm=unreachable riscv=Ret riscv32=Ret mips=Ret ppc=Ret arm32=Ret sparc=Ret loong=Ret 8051=Ret avr=Ret x86=Ret z80=Ret 6502=Ret m68k=Ret msp430=Ret freedos=Ret xtensa=Ret pic=Ret stm8=Ret evm=Ret plan9=Ret custom_mcu=Ret)");
        Ok(())
    } else {
        println!("DDC test: FAIL");
        Err(types::IsaError::PlatformError { msg: "DDC mismatch".into() })
    }
}

#[inline(never)]
fn ddc_sim(tir: &[tir::TirInst]) -> Result<bool, types::IsaError> {
    let sim = simulator::simulate(tir)?;
    println!("DDC test: sim     exit={:?} steps={}", sim.exit_reason, sim.steps);
    Ok(sim.exit_reason == crate::simulator::SimExitReason::Ret)
}
#[inline(never)]
fn ddc_arm64(tir: &[tir::TirInst]) -> Result<bool, types::IsaError> {
    let out = emit::emit(tir, platform::PlatformKind::Android)?;
    let elf = arm64_elf_link::link_arm64_elf(&out.code, &out.data)?;
    let exec = crate::arm64_interp::run_arm64_elf(&elf.bytes);
    println!("DDC test: exec    exit={:?} steps={}", exec.exit_reason, exec.steps);
    Ok(exec.exit_reason == crate::arm64_interp::ExecExitReason::Ret)
}
