fn cmd_test_ddc_arith() -> Result<(), types::IsaError> {
    let fixture = find_fixture("01_arith.ty")?;
    let src = fs::read_to_string(&fixture).map_err(|e| types::IsaError::IoError { msg: e.to_string() })?;
    let tir = executor::compile_ty_source_to_tir(&src)?;

    let sim = simulator::simulate(&tir)?;
    let sim_slot0 = sim.state.get(&0).copied().unwrap_or(0);
    println!("01_arith DDC: sim      exit={:?} slot0={} slot1={} steps={}", sim.exit_reason, sim_slot0, sim.state.get(&1).copied().unwrap_or(0), sim.steps);
    let sim_ok = sim.exit_reason == simulator::SimExitReason::Ret && sim_slot0 == 8;

    let arm64_ok = arith_arm64(&tir)?;
    let riscv64_ok = arith_riscv64(&tir)?;
    let riscv32_ok = arith_riscv32(&tir)?;
    let mips_ok = arith_mips(&tir)?;
    let ppc_ok = arith_ppc(&tir)?;
    let arm32_ok = arith_arm32(&tir)?;
    let sparc_ok = arith_sparc(&tir)?;
    let loong_ok = arith_loong(&tir)?;
    let e8051_ok = arith_8051(&tir)?;
    let avr_ok = arith_avr(&tir)?;
    let x86_ok = arith_x86(&tir)?;
    let z80_ok = arith_z80(&tir)?;
    let m6502_ok = arith_6502(&tir)?;
    let m68k_ok = arith_m68k(&tir)?;
    let msp430_ok = arith_msp430(&tir)?;
    let freedos_ok = arith_freedos(&tir)?;
    let xtensa_ok = arith_xtensa(&tir)?;
    let pic_ok = arith_pic(&tir)?;
    let stm8_ok = arith_stm8(&tir)?;
    let evm_ok = arith_evm(&tir)?;
    let plan9_ok = arith_plan9(&tir)?;
    let win32_ok = arith_win32(&tir)?;
    let linux_ok = arith_linux(&tir)?;

    // Core ELF + plan9 + x86 + win32/linux production x64: fatal
    let core = [sim_ok, arm64_ok, riscv64_ok, riscv32_ok, mips_ok, ppc_ok, arm32_ok, sparc_ok, loong_ok, x86_ok, plan9_ok, win32_ok, linux_ok];
    let core_pass = core.iter().filter(|&&x| x).count();
    let core_total = core.len();

    // MCU / exotic: soft (reported, non-fatal)
    let soft = [e8051_ok, avr_ok, z80_ok, m6502_ok, m68k_ok, msp430_ok, freedos_ok, xtensa_ok, pic_ok, stm8_ok, evm_ok];
    let soft_pass = soft.iter().filter(|&&x| x).count();
    let soft_total = soft.len();

    println!("01_arith DDC: {core_pass}/{core_total} CORE PASS + {soft_pass}/{soft_total} MCU PASS (slot0=8)");
    if soft_pass != soft_total {
        return Err(types::IsaError::ParseError {
            line: 0,
            msg: format!("01_arith DDC: only {soft_pass}/{soft_total} MCU paths PASS (need all 11 MCU slot0=8)"),
        });
    }
    if core_pass != core_total {
        return Err(types::IsaError::ParseError {
            line: 0,
            msg: format!("01_arith DDC: only {core_pass}/{core_total} core paths PASS (need sim+ELF majors+x86+plan9+win32+linux slot0=8)"),
        });
    }
    println!("01_arith DDC: ALL {core_total} CORE + {soft_total} MCU PATHS PASS (fatal)");
    Ok(())
}

