fn check_g02(root: &std::path::Path) -> Result<String, String> {
    let ty_path = root.join("yoyo/tests/golden/02_addv_orv.ty");
    let addv_path = root.join("yoyo/tests/golden/expected/02_addv_orv.addv.hex");
    let orv_path = root.join("yoyo/tests/golden/expected/02_addv_orv.orv.hex");
    let sha_path = root.join("yoyo/tests/golden/expected/02_addv_orv.text.sha256");
    for p in [&ty_path, &addv_path, &orv_path, &sha_path] {
        if !p.is_file() {
            return Err(format!("missing {}", p.display()));
        }
    }
    let addv = assembler::emit_addv(0x50, 0x51).map_err(|e| e.to_string())?;
    let orv = assembler::emit_orv(0x50, 0x51).map_err(|e| e.to_string())?;
    let addv_exp = load_expected_hex(&addv_path).map_err(|e| e.to_string())?;
    let orv_exp = load_expected_hex(&orv_path).map_err(|e| e.to_string())?;
    if addv != addv_exp {
        return Err(format!(
            "ADDV mismatch: got {} want {}",
            hex_encode(&addv),
            hex_encode(&addv_exp)
        ));
    }
    if orv != orv_exp {
        return Err(format!(
            "ORV mismatch: got {} want {}",
            hex_encode(&orv),
            hex_encode(&orv_exp)
        ));
    }
    if addv == orv {
        return Err("ORV aliases ADDV (MUST differ)".into());
    }
    let src = fs::read_to_string(&ty_path).map_err(|e| e.to_string())?;
    let out = executor::compile_ty_source(&src, PlatformKind::Stub).map_err(|e| e.to_string())?;
    if !contains_slice(&out.code, &addv) || !contains_slice(&out.code, &orv) {
        return Err("fixture code missing ADDV or ORV stream".into());
    }
    let text = format!(
        "addv={}\norv={}\n",
        hex_encode(&addv_exp),
        hex_encode(&orv_exp)
    );
    let got_sha = ddc::sha256_hex(text.as_bytes());
    let exp_sha: String = fs::read_to_string(&sha_path)
        .map_err(|e| e.to_string())?
        .chars()
        .filter(|c| !c.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    if got_sha != exp_sha {
        return Err(format!("text.sha256 mismatch: got {got_sha} want {exp_sha}"));
    }
    Ok(format!("addv!=orv sha256={}", &got_sha[..16.min(got_sha.len())]))
}

/// G03: CMP+JE patches rel32 to labeled handler.
fn check_g03(root: &std::path::Path) -> Result<String, String> {
    let ty_path = root.join("yoyo/tests/golden/03_cmp_je.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/03_cmp_je.code.hex");
    if !ty_path.is_file() {
        return Err(format!("missing fixture {}", ty_path.display()));
    }
    if !exp_path.is_file() {
        return Err(format!("missing expected {}", exp_path.display()));
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    let src = fs::read_to_string(&ty_path).map_err(|e| e.to_string())?;
    let out = executor::compile_ty_source(&src, PlatformKind::Stub).map_err(|e| e.to_string())?;
    if out.code != expected {
        return Err(format!(
            "mismatch: got {} want {}",
            hex_encode(&out.code),
            hex_encode(&expected)
        ));
    }
    // JE opcode 0F 84 must appear; rel32 at +2 must point inside the buffer.
    let je_idx = match out.code.windows(2).position(|w| w == [0x0F, 0x84]) {
        Some(i) => i,
        None => return Err("JE opcode 0F 84 missing in stream".into()),
    };
    if je_idx + 6 > out.code.len() {
        return Err("JE truncated".into());
    }
    let rel32 = i32::from_le_bytes(out.code[je_idx + 2..je_idx + 6].try_into().unwrap());
    let target = (je_idx as i32) + 2 + 4 + rel32;
    if target < 0 || target as usize >= out.code.len() {
        return Err(format!("JE rel32={rel32} out of range (target={target})"));
    }
    let cmp = assembler::emit_cmp(0x50, 0x51).map_err(|e| e.to_string())?;
    let cmp_idx = match out
        .code
        .windows(cmp.len())
        .position(|w| w == cmp.as_slice())
    {
        Some(i) => i,
        None => return Err("CMP stream missing in fixture".into()),
    };
    if cmp_idx > je_idx {
        return Err(format!(
            "CMP must precede JE (cmp@{cmp_idx}, je@{je_idx})"
        ));
    }
    Ok(format!(
        "je@{je_idx} rel32={rel32} target=0x{:x} cmp@{cmp_idx}",
        target
    ))
}

/// G04: CALL/RET stack pair.
fn check_g04(root: &std::path::Path) -> Result<String, String> {
    let ty_path = root.join("yoyo/tests/golden/04_call_ret.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/04_call_ret.code.hex");
    if !ty_path.is_file() {
        return Err(format!("missing fixture {}", ty_path.display()));
    }
    if !exp_path.is_file() {
        return Err(format!("missing expected {}", exp_path.display()));
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    let src = fs::read_to_string(&ty_path).map_err(|e| e.to_string())?;
    let out = executor::compile_ty_source(&src, PlatformKind::Stub).map_err(|e| e.to_string())?;
    if out.code != expected {
        return Err(format!(
            "mismatch: got {} want {}",
            hex_encode(&out.code),
            hex_encode(&expected)
        ));
    }
    let call_idx = match out.code.iter().position(|b| *b == 0xE8) {
        Some(i) => i,
        None => return Err("CALL opcode 0xE8 missing".into()),
    };
    if call_idx + 5 > out.code.len() {
        return Err("CALL truncated".into());
    }
    let call_rel = i32::from_le_bytes(out.code[call_idx + 1..call_idx + 5].try_into().unwrap());
    let call_target = (call_idx as i32) + 1 + 4 + call_rel;
    if call_target < 0 || call_target as usize >= out.code.len() {
        return Err(format!("CALL rel32={call_rel} out of range (target={call_target})"));
    }
    let ret_count = out.code.iter().filter(|b| **b == 0xC3).count();
    if ret_count < 2 {
        return Err(format!("expected 鈮? RET (0xC3); got {ret_count}"));
    }
    let first_ret = out.code.iter().position(|b| *b == 0xC3).unwrap();
    if first_ret <= call_idx {
        return Err(format!(
            "CALL@{call_idx} must precede first RET@{first_ret}"
        ));
    }
    Ok(format!(
        "call@{call_idx} rel32={call_rel} target=0x{:x} rets={ret_count}",
        call_target
    ))
}

/// G05: Named slots 鈮?hex rewrite (Appendix F / Part 8 smoke).
fn check_g05(root: &std::path::Path) -> Result<String, String> {
    let ty_path = root.join("yoyo/tests/golden/05_named_slots.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/05_named_slots.code.hex");
    if !ty_path.is_file() {
        return Err(format!("missing fixture {}", ty_path.display()));
    }
    if !exp_path.is_file() {
        return Err(format!("missing expected {}", exp_path.display()));
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    let src = fs::read_to_string(&ty_path).map_err(|e| e.to_string())?;
    let out = executor::compile_ty_source(&src, PlatformKind::Stub).map_err(|e| e.to_string())?;
    if out.code != expected {
        return Err(format!(
            "mismatch: got {} want {}",
            hex_encode(&out.code),
            hex_encode(&expected)
        ));
    }
    // Pin must reference slot disp bytes for bound slots 0x50/0x51.
    for &needle in &[0x80u8, 0x02, 0x88, 0x02] {
        if !out.code.contains(&needle) {
            return Err(format!(
                "expected slot disp byte 0x{needle:02X} missing"
            ));
        }
    }
    // Smoke: stock_gui.ty must compile and end with RET.
    let stock_path = root.join("yoyo/projects/stock_gui.ty");
    if !stock_path.is_file() {
        return Err(format!("missing stock_gui.ty ({})", stock_path.display()));
    }
    let stock_src = fs::read_to_string(&stock_path).map_err(|e| e.to_string())?;
    let stock_out = executor::compile_ty_source(&stock_src, PlatformKind::Stub)
        .map_err(|e| format!("stock_gui.ty compile: {e}"))?;
    if stock_out.code.is_empty() || *stock_out.code.last().unwrap() != 0xC3 {
        return Err("stock_gui.ty must end with RET (0xC3)".into());
    }
    Ok(format!(
        "code={} stock_gui={}B",
        hex_encode(&out.code),
        stock_out.code.len()
    ))
}

fn check_selfhost_min(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_compile_stub.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_compile_stub.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected != [0x90, 0xC3] {
        return Err(format!("expected pin must equal 90c3, got {}", hex_encode(&expected)));
    }

    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let compiled = executor::compile_one_handler(&canonical_src, 0x05, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if compiled.code != expected {
        return Err(format!(
            "M_rust canonical H_05 mismatch: got {} want {}",
            hex_encode(&compiled.code),
            hex_encode(&expected)
        ));
    }
    Ok(format!(
        "M_rust read yoyo.ty H_05 and emitted {} via opcode A0+FF",
        hex_encode(&compiled.code)
    ))
}

/// W-SM chained: per-peer Rust golden for the *combined* H_05 + H_06 sequence
/// read from canonical yoyo.ty. Pins H_06 emits 90 90 C3 (raw NOP NOP RET) and
/// that the two-handler concatenated emit is 90 C3 90 90 C3. JS is **not**
