/// body-extend-007 H_40: 0x80 LDB dd ss oo —3-arg load-byte at oo=8
/// (imm8 path: 8 鈭?[-128, 127]) at selector 0x2E. Pin 23B:
/// 498b87000300004883c008480fb60049898780020000c3. Mirrors ldb_body
/// template but exercises the add_imm imm8 code path. Disjoint from
/// H_37 (oo=0 short-circuits add_imm entirely, 19B). Both peers
/// compose identical bytes via the same x86-64 primitives:
///   JS:   loadState(0x60,rax) + addImmRax(8) + [0x48,0x0f,0xb6,0x00]
///         + storeState(0x50,rax) + 0xC3 (23B)
///   Rust: emit_ldb(0x50, 0x60, 8) 鈫?load_state(0x60,rax) +
///         add_imm(rax, 8) (imm8 path) + movzx + store_state(0x50,rax)
///         + ret() (23B)
fn check_selfhost_min_ldb_off8_handler(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_ldb_off8_handler.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_ldb_off8_handler.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    let want: [u8; 23] = [
        0x49, 0x8B, 0x87, 0x00, 0x03, 0x00, 0x00, // load_state(0x60, rax) —disp 0x300 LE
        0x48, 0x83, 0xC0, 0x08,                   // add rax, 8 (imm8 path: 8 鈭?[-128, 127])
        0x48, 0x0F, 0xB6, 0x00,                   // movzx rax, byte [rax]
        0x49, 0x89, 0x87, 0x80, 0x02, 0x00, 0x00, // store_state(0x50, rax) —disp 0x280 LE
        0xC3,                                     // ret
    ];
    if expected != want {
        return Err(format!(
            "expected LDB-OFF8-HANDLER pin must be 23B 498b87000300004883c008480fb60049898780020000c3, got {}",
            hex_encode(&expected)
        ));
    }
    if expected.len() != 23 {
        return Err(format!(
            "LDB-OFF8-HANDLER pin must be 23B, got {}B",
            expected.len()
        ));
    }
    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }
    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let compiled = executor::compile_one_handler(&canonical_src, 0x2E, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if compiled.code != expected {
        return Err(format!(
            "M_rust canonical H_2E mismatch: got {} want {}",
            hex_encode(&compiled.code),
            hex_encode(&expected)
        ));
    }
    // Reject imm32 path: the encoder MUST stay on imm8 path for oo=8.
    let imm32: [u8; 3] = [0x48, 0x81, 0xC0];
    if compiled.code.windows(3).any(|w| w == imm32) {
        return Err("LDB-OFF8-HANDLER emitted imm32 path for oo=8 (premature imm32 escalation)".into());
    }
    Ok(format!(
        "M_rust read yoyo.ty H_2E and emitted {} via opcode ldb+oo=8+FF (imm8 path)",
        hex_encode(&compiled.code)
    ))
}

fn check_selfhost_min_ldb_off127_handler(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_ldb_off127_handler.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_ldb_off127_handler.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub).map_err(|e| e.to_string())?;
    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let compiled = executor::compile_one_handler(&canonical_src, 0x2F, PlatformKind::Stub).map_err(|e| e.to_string())?;
    if expected.len() != 23 || fixture.code != expected || compiled.code != expected {
        return Err(format!("LDB-OFF127-HANDLER mismatch: fixture={} canonical={} expected={}", hex_encode(&fixture.code), hex_encode(&compiled.code), hex_encode(&expected)));
    }
    if !compiled.code.windows(4).any(|w| w == [0x48, 0x83, 0xC0, 0x7F])
        || compiled.code.windows(7).any(|w| w == [0x48, 0x81, 0xC0, 0x7F, 0, 0, 0]) {
        return Err("LDB-OFF127-HANDLER failed signed-imm8 right-edge assertion".into());
    }
    Ok(format!("M_rust read yoyo.ty H_2F and emitted {} via opcode ldb+oo=127+FF (imm8 path)", hex_encode(&compiled.code)))
}

/// body-extend-009 H_42: 0x80 LDB dd ss oo —3-arg load-byte at oo=0x50
/// (imm8 path: 0x50 鈭?[-128, 127] unsigned 80) at selector 0x30. Pin 23B:
/// 498b87000300004883c050480fb60049898780020000c3. Mirrors
/// check_selfhost_min_ldb_off127_handler template but exercises the
/// LEFT-side imm8 byte (0x50 vs H_41's 0x7f). Both peers compose identical
/// bytes via the same x86-64 primitives:
///   JS:   loadState(0x60,rax) + addImmRax(0x50) + [0x48,0x0f,0xb6,0x00]
///         + storeState(0x50,rax) + 0xC3 (23B)
///   Rust: emit_ldb(0x50, 0x60, 0x50) 鈫?load_state(0x60,rax) +
///         add_imm(rax, 0x50) (imm8 path) + movzx + store_state(0x50,rax)
