/// W-SM control flow: Rust-only golden for H_21 `0x71 JE hh`.
/// Fixture pins exact JE rel32 (0F 84) backward to H_00.
/// Canonical full compile must contain at least one JE valid rel32.
fn check_selfhost_min_je(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_je.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_je.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected.len() != 76 {
        return Err(format!("expected pin must be 76B, got {}B", expected.len()));
    }
    // JE opcode 0F 84 should be at offset 69 in the fixture
    if expected[69..71] != [0x0F, 0x84] {
        return Err(format!("expected JE (0F 84) at offset 69, got {:02X} {:02X}", expected[69], expected[70]));
    }
    let rel = i32::from_le_bytes(expected[71..75].try_into().unwrap());
    let target = (69i32 + 6) + rel;
    if target != 0 {
        return Err(format!("expected JE target=0, got target={target} (rel32={rel})"));
    }

    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    // Canonical full compile: verify JE (0F 84) with valid backward rel32
    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let full = executor::compile_ty_source(&canonical_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    let je_idx = match full.code.windows(2).position(|w| w == [0x0F, 0x84]) {
        Some(i) => i,
        None => return Err("canonical compile: JE (0F 84) missing".into()),
    };
    if je_idx + 6 > full.code.len() {
        return Err("canonical compile: JE truncated".into());
    }
    let rel32 = i32::from_le_bytes(full.code[je_idx + 2..je_idx + 6].try_into().unwrap());
    let je_target = (je_idx as i32) + 6 + rel32;
    if je_target < 0 || je_target as usize >= full.code.len() {
        return Err(format!(
            "canonical compile: JE rel32={rel32} out of range (target={je_target})"
        ));
    }
    if rel32 >= 0 {
        return Err(format!(
            "canonical compile: JE rel32={rel32} must be backward (negative)"
        ));
    }
    Ok(format!(
        "fixture={} canonical=JE@{} rel32={} target=0x{:x}",
        hex_encode(&fixture.code),
        je_idx,
        rel32,
        je_target
    ))
}

/// W-SM control flow: G-SM-JCC-ALL —all 9 Jcc handlers (H_22-H_2A).
/// Fixture pins exact 540B output with all 9 Jcc rel32 targeting H_00.
/// Canonical compile must contain all 9 x64 Jcc opcodes.
fn check_selfhost_min_jcc_all(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_jcc_all.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_jcc_all.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected.len() != 540 {
        return Err(format!("expected pin must be 540B, got {}B", expected.len()));
    }

    // All 9 x64 Jcc opcode suffixes (second byte of 0F XX)
    let jcc_x64: [u8; 9] = [0x85, 0x8C, 0x8D, 0x8E, 0x8F, 0x82, 0x83, 0x86, 0x87];

    // Fixture compile check
    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }
    // Verify each Jcc opcode appears exactly once and targets offset 0
    let mut seen = 0u32;
    for &suffix in &jcc_x64 {
        if let Some(idx) = fixture.code.windows(2).position(|w| w == [0x0F, suffix]) {
            if idx + 6 > fixture.code.len() {
                return Err(format!("Jcc {:02X} truncated at idx {idx}", suffix));
            }
            let rel = i32::from_le_bytes(fixture.code[idx + 2..idx + 6].try_into().unwrap());
            let target = (idx as i32) + 6 + rel;
            if target != 0 {
                return Err(format!(
                    "fixture Jcc {:02X} target={target} != 0 (rel={rel})",
                    suffix
                ));
            }
            seen += 1;
        }
    }
    if seen != 9 {
        return Err(format!("fixture: only {seen}/9 Jcc opcodes found"));
    }

    // Canonical full compile: verify all 9 Jcc opcodes present with backward rel32
    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let full = executor::compile_ty_source(&canonical_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    let mut can_seen = 0u32;
    for &suffix in &jcc_x64 {
        if let Some(idx) = full.code.windows(2).position(|w| w == [0x0F, suffix]) {
            if idx + 6 > full.code.len() {
                return Err(format!("canonical Jcc {:02X} truncated at idx {idx}", suffix));
            }
            let rel = i32::from_le_bytes(full.code[idx + 2..idx + 6].try_into().unwrap());
            let target = (idx as i32) + 6 + rel;
            if target < 0 || target as usize >= full.code.len() {
                return Err(format!(
                    "canonical Jcc {:02X} rel={rel} out of range (target={target})",
                    suffix
                ));
            }
            if rel >= 0 {
                return Err(format!(
                    "canonical Jcc {:02X} rel={rel} must be backward (negative)",
                    suffix
                ));
            }
            can_seen += 1;
        }
    }
    if can_seen != 9 {
        return Err(format!("canonical: only {can_seen}/9 Jcc opcodes found"));
    }

    Ok(format!(
        "fixture=540B canonical={can_seen}/9 Jcc found, all backward to valid targets"
    ))
}

/// W-SM I/O: Rust-only golden for H_2B ALLOC, H_2C LOAD_FILE, H_2D WRITE_FILE.
/// Stub backend now matches JS (movabs+store), so 2-chain DDC is preserved.
/// Fixture pins exact 72B output. Canonical compile verifies all 3 ops present.
fn check_selfhost_min_io(root: &std::path::Path) -> Result<String, String> {
    let fixture_path = root.join("yoyo/tests/golden/selfhost_min_io.ty");
    let exp_path = root.join("yoyo/tests/golden/expected/selfhost_min_io.code.hex");
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected.len() != 72 {
        return Err(format!("expected pin must be 72B, got {}B", expected.len()));
    }

    // Fixture: 4 handlers 脳 18B each (movabs+store+ret). ALLOC size=0x1000 gives unique byte.
    let alloc_marker: [u8; 3] = [0x48, 0xB8, 0x00]; // movabs rax, lo-byte
    if expected[18] != 0x48 || expected[19] != 0xB8 || expected[20] != 0x00 {
        return Err("expected pin: ALLOC (H_2B) must start at offset 18".into());
    }
    // Check ALLOC stores 0x1000 (bytes 20-23 should be 00 10 00 00)
    if expected[20..24] != [0x00, 0x10, 0x00, 0x00] {
        return Err("expected pin: ALLOC size must be 0x1000".into());
    }

    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    // Canonical full compile: verify all 3 I/O handlers present
    // (each is movabs+store+C3; ALLOC with 0x1000 is unique)
    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let full = executor::compile_ty_source(&canonical_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    // Check ALLOC 0x1000 marker exists
    let alloc_pat = [0x48, 0xB8, 0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]; // movabs rax, 0x1000
    if !full.code.windows(alloc_pat.len()).any(|w| w == alloc_pat) {
        return Err("canonical compile: ALLOC (movabs 0x1000) missing".into());
    }
    // At least one of LOAD_FILE or WRITE_FILE stores 0 to S[0x50]
    let zero_store = [0x49, 0x89, 0x87, 0x80, 0x02, 0x00, 0x00]; // store_state S[0x50]
    let store_count = full.code.windows(zero_store.len()).filter(|w| w == &zero_store).count();
    if store_count < 3 {
        return Err(format!(
            "canonical compile: expected 鈮? store_state S[0x50] patterns, got {store_count}"
        ));
    }

    Ok(format!("fixture=72B canonical=3 I/O handlers present"))
}

fn check_selfhost_min_arith(
    root: &std::path::Path,
    hh: u16,
    fixture_name: &str,
    _opcode: u8,
    opcode_pat: &[u8],
    op_name: &str,
) -> Result<String, String> {
    let fixture_path = root.join(format!("yoyo/tests/golden/{fixture_name}.ty"));
    let exp_path = root.join(format!("yoyo/tests/golden/expected/{fixture_name}.code.hex"));
    let canonical_path = root.join("yoyo/projects/yoyo.ty");
    for path in [&fixture_path, &exp_path, &canonical_path] {
        if !path.is_file() {
            return Err(format!("missing {}", path.display()));
        }
    }
    let expected = load_expected_hex(&exp_path).map_err(|e| e.to_string())?;
    if expected.len() != 18
        || expected[0..7] != [0x49, 0x8B, 0x87, 0x80, 0x02, 0x00, 0x00]
        || expected[10..17] != [0x49, 0x89, 0x87, 0x80, 0x02, 0x00, 0x00]
        || expected[17] != 0xC3
    {
        return Err(format!(
            "expected pin has wrong shape: {}",
            hex_encode(&expected)
        ));
    }

    let fixture_src = fs::read_to_string(&fixture_path).map_err(|e| e.to_string())?;
    let fixture = executor::compile_ty_source(&fixture_src, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if fixture.code != expected {
        return Err(format!(
            "fixture mismatch: got {} want {}",
            hex_encode(&fixture.code),
            hex_encode(&expected)
        ));
    }

    let canonical_src = fs::read_to_string(&canonical_path).map_err(|e| e.to_string())?;
    let compiled = executor::compile_one_handler(&canonical_src, hh, PlatformKind::Stub)
        .map_err(|e| e.to_string())?;
    if compiled.code != expected {
        return Err(format!(
            "M_rust canonical H_{hh:02X} mismatch: got {} want {}",
            hex_encode(&compiled.code),
            hex_encode(&expected)
        ));
    }
    if !contains_slice(&compiled.code, opcode_pat) {
        return Err(format!(
            "H_{hh:02X} missing {op_name} rax ({})",
            hex_encode(opcode_pat)
        ));
    }
    Ok(format!(
        "M_rust read yoyo.ty H_{hh:02X} and emitted {} via opcode {op_name}+FF",
        hex_encode(&compiled.code)
    ))
}

fn contains_slice(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

fn load_expected_hex(path: &std::path::Path) -> Result<Vec<u8>, types::IsaError> {
    let exp_text = fs::read_to_string(path).map_err(|e| types::IsaError::IoError {
        msg: e.to_string(),
    })?;
    let exp_hex: String = exp_text.chars().filter(|c| !c.is_whitespace()).collect();
    hex_decode(&exp_hex)
}

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn hex_decode(s: &str) -> Result<Vec<u8>, types::IsaError> {
    let s = s.to_ascii_lowercase();
    if s.len() % 2 != 0 || !s.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err(types::IsaError::ParseError {
            line: 0,
            msg: format!("bad expected hex: {s}"),
        });
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let hi = hex_nibble(bytes[i])?;
        let lo = hex_nibble(bytes[i + 1])?;
        out.push((hi << 4) | lo);
        i += 2;
    }
    Ok(out)
}

fn hex_nibble(b: u8) -> Result<u8, types::IsaError> {
    match b {
        b'0'..=b'9' => Ok(b - b'0'),
        b'a'..=b'f' => Ok(b - b'a' + 10),
        _ => Err(types::IsaError::ParseError {
            line: 0,
            msg: format!("bad hex nibble {}", b as char),
        }),
    }
}
